/**
 * M6 Workflow: single-path routing over the wire graph extracted in M4.
 *
 * Deterministic by construction: the only I/O is the awaited `executeNode`
 * Activity call (via `proxyActivities`); no Date.now()/Math.random()/fs/etc.
 * anywhere in this file. `resolveNext` and `runFlow` are plain, side-effect
 * free functions so they can be unit-tested directly (see A2 answer #2 in
 * the M6 handoff for the grep proving this).
 *
 * Single-path scope decision (per the milestone plan): only the FIRST send
 * on the port a node actually sent on is followed - fan-out to further
 * destinations on that port, or to other output ports, is intentionally
 * ignored. Multi-path/fan-out routing is out of scope for M6.
 */

"use strict";

const { proxyActivities, ApplicationFailure } = require("@temporalio/workflow");

// Non-retryable node/business errors (M5 `activities.js` codes). These are
// never worth retrying: a bad wire graph, a stale flow deploy, or a node's
// own thrown error will fail identically on every retry attempt.
const NON_RETRYABLE_CODES = new Set([
    "FLOW_VERSION_MISMATCH",
    "NODE_NOT_FOUND",
    "NODE_ERROR",
    "NODE_TIMEOUT"
]);

/**
 * Given the wire graph and the first send emitted by `nodeId`, resolve the
 * single next node id to invoke - the first destination wired to the port
 * the message was sent on. Returns undefined when there is nothing further
 * to route to (end of path, or `send` itself is undefined/null).
 *
 * @param {Object<string, Array<Array<string>>>} graph
 * @param {string} nodeId - the node that produced `send`
 * @param {{port:number, msg:object}} [send]
 * @returns {string|undefined}
 */
function resolveNext(graph, nodeId, send) {
    if (!send) {
        return undefined;
    }
    const wires = graph && graph[nodeId];
    const port = wires && wires[send.port];
    return (port && port[0]) || undefined;
}

/**
 * Pure routing loop, parameterized over `executeNode` so it can be unit
 * tested with a mock Activity function - the actual Temporal Workflow entry
 * point (`executeFlow` below) supplies the real, Temporal-proxied Activity.
 *
 * Any Activity result carrying `error` ends the run immediately by throwing
 * an `ApplicationFailure` marked `nonRetryable: true` (approach (a) from the
 * M6 plan - see handoff for the rejected alternative and why).
 *
 * @param {{executeNode:function, graph:object, flowVersion:string, startNode:string, startMsg:*}} input
 * @returns {Promise<{flowVersion:string, lastNode:(string|undefined)}>}
 */
async function runFlow({ executeNode, graph, flowVersion, startNode, startMsg }) {
    let node = startNode;
    let msg = startMsg;
    let lastNode;

    while (node) {
        const result = await executeNode({ flowVersion, nodeId: node, msg });
        if (result.error) {
            throw ApplicationFailure.create({
                message: `node ${node} failed: [${result.error.code}] ${result.error.message}`,
                type: result.error.code,
                nonRetryable: NON_RETRYABLE_CODES.has(result.error.code),
                details: [result.error]
            });
        }
        lastNode = node;
        const send = result.sends && result.sends[0];
        msg = send ? send.msg : undefined;
        node = resolveNext(graph, node, send);
    }

    return { flowVersion, lastNode };
}

// Activity timeout: 30s, well above Capture's DEFAULT_TIMEOUT_MS (5s, see
// capture.js) so a NODE_TIMEOUT from Capture always surfaces first, instead
// of Temporal killing the Activity call before Capture's own timer fires
// (see M6 handoff A2 #4 for the full ordering argument).
const { executeNode } = proxyActivities({
    startToCloseTimeout: "30s",
    // Retry policy for transient infra failures (thrown Activity errors,
    // e.g. worker crash mid-call). Node-level business errors never throw
    // here - executeNode always resolves - so this policy only ever governs
    // real infra retries, not node.error()/timeout retries (see A2 #1).
    retry: { maximumAttempts: 3, initialInterval: "1s", backoffCoefficient: 2 }
});

/**
 * Temporal Workflow entry point. Registered by `worker.js` under this
 * function's name.
 * @param {{graph:object, flowVersion:string, startNode:string, startMsg:*}} input
 */
async function executeFlow(input) {
    return runFlow({ executeNode, graph: input.graph, flowVersion: input.flowVersion, startNode: input.startNode, startMsg: input.startMsg });
}

module.exports = { resolveNext, runFlow, executeFlow };
